const BASE = '{{WA_API_BASE}}/api/v1';
const headers = {
  'Authorization': 'Bearer ' + process.env.SM_API_KEY, // sm_live_your_api_key
  'Content-Type': 'application/json',
};

// 1. Check that the template is approved (needs the templates:read scope)
const list = await fetch(
  `${BASE}/templates?status=APPROVED&name=order_confirmation&language=en_US`,
  { headers },
);
const { data: templates } = await list.json();
if (templates.items.length === 0) throw new Error('order_confirmation is not approved yet');

// 2. Send it (needs the messages:send scope)
const res = await fetch(`${BASE}/messages`, {
  method: 'POST',
  headers: { ...headers, 'Idempotency-Key': 'order-1042-confirmed' },
  body: JSON.stringify({
    to: '+919812345678',
    type: 'template',
    template: {
      name: 'order_confirmation',
      language: 'en_US',
      parameters: [{ text: 'Asha' }, { text: '#1042' }],
    },
    clientReference: 'order-1042',
  }),
});

const { data } = await res.json();
console.log(data.id, data.status);
